function _lookup(ch) {
    return Object.prototype.hasOwnProperty.call(EMOJI_MAP, ch) ? EMOJI_MAP[ch] : undefined;
}

// Resolves an emoji string to its bundled asset path, or "" if this exact
// sequence isn't in the map. Matrix clients disagree on whether to include the
// U+FE0F emoji-presentation variation selector on a reaction key, so a plain
// lookup miss also retries with it added/removed before giving up.
function emojiAsset(ch) {
    if (!ch) return "";
    var f = _lookup(ch);
    if (f) return "asset:///emoji/" + f;
    var VS16 = "\uFE0F";
    if (ch.length >= 1 && ch.charAt(ch.length - 1) !== VS16) {
        f = _lookup(ch + VS16);
        if (f) return "asset:///emoji/" + f;
    }
    if (ch.length >= 1 && ch.charAt(ch.length - 1) === VS16) {
        f = _lookup(ch.substring(0, ch.length - 1));
        if (f) return "asset:///emoji/" + f;
    }
    return "";
}
